@dataclass
class ModelArguments:
    """
    Arguments pertaining to which model/config/tokenizer we are going to fine-tune from.
    """

    model_name_or_path: str = field(
        metadata={"help": "Path to pretrained model or model identifier from huggingface.co/models"}
    )
    config_name: Optional[str] = field(
        default=None, metadata={"help": "Pretrained config name or path if not the same as model_name"}
    )
    tokenizer_name: Optional[str] = field(
        default=None, metadata={"help": "Pretrained tokenizer name or path if not the same as model_name"}
    )
    cache_dir: Optional[str] = field(
        default=None,
        metadata={"help": "Path to directory to store the pretrained models downloaded from huggingface.co"},
    )
    share_adapter: bool = field(
        default=False, metadata={"help": "whether share the adapter across the layers."}
    )
    model_revision: str = field(
        default="main",
        metadata={"help": "The specific model version to use (can be a branch name, tag name or commit id)."},
    )
    sparsity: Optional[float] = field(
        default=1.0,
        metadata={
            "help": "sparsity of the subnet"
        },
    )
    use_auth_token: bool = field(
        default=False,
        metadata={
            "help": (
                "Will use the token generated when running `transformers-cli login` (necessary to use this script "
                "with private models)."
            )
        },
    )
    num_layer: Optional[int] = field(
        default=2,
        metadata={"help": "number of weight-tied layers."},
    )
    density: Optional[float] = field(
        default=0.5,
        metadata={"help": "density of the weight-tied layers."},
    )

# Code block from examples/pytorch/question-answering/run_qa.py demonstrating shared adapter setup and weight tying
config.share_adapter = model_args.share_adapter
config.sparsity=model_args.sparsity

if adapter_args.train_adapter:
    task_name = data_args.dataset_name or "squad"
    if task_name not in model.config.adapters:
        adapter_config = AdapterConfig.load(
            adapter_args.adapter_config,
            non_linearity=adapter_args.adapter_non_linearity,
            reduction_factor=adapter_args.adapter_reduction_factor,
            prefix_length=adapter_args.prefix_length,
            share_adapter=model_args.share_adapter,
            r=adapter_args.lora_r,
            alpha=adapter_args.lora_alpha,
            sparsity=model_args.sparsity,
            num_layer=model_args.num_layer,
            density=model_args.density,
        )
        if model_args.share_adapter:
            model.add_shared_adapter(task_name, config=adapter_config)
        else:
            model.add_adapter(task_name, config=adapter_config)

        # share weights for all adapters
        if model_args.share_adapter and isinstance(adapter_config, LoRAConfig):
            # This loop applies weight-tying for DeBERTa models across 12 layers.
            # The num_layer argument passed to AdapterConfig.load influences the adapter creation,
            # but this specific loop hardcodes 12 layers for existing module access.
            for i in range(12):
                model.deberta.encoder.layer[i].attention.self.query_proj.loras[task_name].lora_A = model.deberta.encoder.layer[0].attention.self.query_proj.loras[task_name].lora_A
                model.deberta.encoder.layer[i].attention.self.query_proj.loras[task_name].lora_B = model.deberta.encoder.layer[0].attention.self.query_proj.loras[task_name].lora_B
                model.deberta.encoder.layer[i].attention.self.value_proj.loras[task_name].lora_A = model.deberta.encoder.layer[0].attention.self.value_proj.loras[task_name].lora_A
                model.deberta.encoder.layer[i].attention.self.value_proj.loras[task_name].lora_B = model.deberta.encoder.layer[0].attention.self.value.loras[task_name].lora_B
    model.train_adapter(task_name)
